CaseLibraryHall caseTimeMachineHallById(String id) {
  return caseTimeMachineHalls.firstWhere(
    (h) => h.id == id,
    orElse: () => caseTimeMachineHalls.first,
  );
}

CaseBook caseTimeMachineCaseById(String id) {
  return caseTimeMachineCases.firstWhere(
    (c) => c.id == id,
    orElse: () => caseTimeMachineCases.first,
  );
}

List<CaseBook> caseTimeMachineCasesForShelf(CaseShelf shelf) {
  return caseTimeMachineCases
      .where((c) => shelf.caseIds.contains(c.id))
      .toList();
}
